-- 001016_gamification_v2 — Gamification catalogue v2 (proposal: Japa.to
-- Complete Gamification Badge Catalogue).
--
-- 1. Extends badge_definitions with catalogue metadata: category, rarity,
--    progression tier/group, secret/limited/featured flags, points reward,
--    availability window, and optional season linkage.
-- 2. Adds trigger_type 'streak_days' for consecutive-day streak badges
--    (evaluated against daily.login activity events).
-- 3. Creates badge_progress (per-user progress toward locked badges),
--    badge_tiers (progressive collection metadata), badge_award_events
--    (auditable award history), badge_seasons (limited-edition windows).
-- 4. Seeds the full badge catalogue (~248 definitions, phased activation)
--    and point rules for newly-emitted activity keys.
--
-- All changes are additive — existing badge evaluation is unaffected.

-- -------------------------------------------------------------------------
-- 1. badge_seasons first (badge_definitions.season_id references it).
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.badge_seasons (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    description text,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT badge_seasons_pkey PRIMARY KEY (id),
    CONSTRAINT badge_seasons_slug_key UNIQUE (slug)
);

-- -------------------------------------------------------------------------
-- 2. badge_definitions catalogue metadata (all nullable/defaulted — zero
--    downtime). season_id added after badge_seasons exists.
-- -------------------------------------------------------------------------
ALTER TABLE public.badge_definitions
    ADD COLUMN IF NOT EXISTS category text,
    ADD COLUMN IF NOT EXISTS rarity text DEFAULT 'common' NOT NULL,
    ADD COLUMN IF NOT EXISTS tier text,
    ADD COLUMN IF NOT EXISTS badge_group text,
    ADD COLUMN IF NOT EXISTS is_secret boolean DEFAULT false NOT NULL,
    ADD COLUMN IF NOT EXISTS is_limited boolean DEFAULT false NOT NULL,
    ADD COLUMN IF NOT EXISTS is_featured boolean DEFAULT false NOT NULL,
    ADD COLUMN IF NOT EXISTS points_reward integer DEFAULT 0 NOT NULL,
    ADD COLUMN IF NOT EXISTS available_from timestamp with time zone,
    ADD COLUMN IF NOT EXISTS available_until timestamp with time zone,
    ADD COLUMN IF NOT EXISTS season_id uuid;

ALTER TABLE public.badge_definitions
    DROP CONSTRAINT IF EXISTS badge_definitions_rarity_check;
ALTER TABLE public.badge_definitions
    ADD CONSTRAINT badge_definitions_rarity_check
    CHECK (rarity = ANY (ARRAY['common','uncommon','rare','epic','legendary','mythic']));

ALTER TABLE public.badge_definitions
    DROP CONSTRAINT IF EXISTS badge_definitions_tier_check;
ALTER TABLE public.badge_definitions
    ADD CONSTRAINT badge_definitions_tier_check
    CHECK (tier IS NULL OR tier = ANY (ARRAY['bronze','silver','gold','platinum','diamond']));

ALTER TABLE public.badge_definitions
    DROP CONSTRAINT IF EXISTS badge_definitions_trigger_type_check;
ALTER TABLE public.badge_definitions
    ADD CONSTRAINT badge_definitions_trigger_type_check
    CHECK (trigger_type = ANY (ARRAY['lifetime_points','activity_count','streak_days','manual']));

ALTER TABLE public.badge_definitions
    DROP CONSTRAINT IF EXISTS badge_definitions_season_id_fkey;
ALTER TABLE public.badge_definitions
    ADD CONSTRAINT badge_definitions_season_id_fkey
    FOREIGN KEY (season_id) REFERENCES public.badge_seasons(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_badge_definitions_category
    ON public.badge_definitions USING btree (category, is_active);
CREATE INDEX IF NOT EXISTS idx_badge_definitions_group
    ON public.badge_definitions USING btree (badge_group) WHERE badge_group IS NOT NULL;

-- -------------------------------------------------------------------------
-- 3. badge_progress — per-user progress toward locked badges (powers the
--    "X / Y to earn" state in the achievement centre).
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.badge_progress (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    badge_id uuid NOT NULL,
    current_count integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT badge_progress_pkey PRIMARY KEY (id),
    CONSTRAINT badge_progress_user_badge_key UNIQUE (user_id, badge_id),
    CONSTRAINT badge_progress_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE,
    CONSTRAINT badge_progress_badge_id_fkey FOREIGN KEY (badge_id) REFERENCES public.badge_definitions(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_badge_progress_user
    ON public.badge_progress USING btree (user_id);

-- -------------------------------------------------------------------------
-- 4. badge_tiers — progression metadata for tiered badge collections
--    (e.g. explorer bronze→diamond). The tier's badge_id links back to the
--    badge_definitions row that represents that level.
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.badge_tiers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    badge_group text NOT NULL,
    tier text NOT NULL,
    name text NOT NULL,
    threshold integer DEFAULT 0 NOT NULL,
    badge_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT badge_tiers_pkey PRIMARY KEY (id),
    CONSTRAINT badge_tiers_group_tier_key UNIQUE (badge_group, tier),
    CONSTRAINT badge_tiers_badge_id_fkey FOREIGN KEY (badge_id) REFERENCES public.badge_definitions(id) ON DELETE SET NULL,
    CONSTRAINT badge_tiers_tier_check CHECK (tier = ANY (ARRAY['bronze','silver','gold','platinum','diamond']))
);
CREATE INDEX IF NOT EXISTS idx_badge_tiers_group
    ON public.badge_tiers USING btree (badge_group, threshold);

-- -------------------------------------------------------------------------
-- 5. badge_award_events — auditable award history (system evaluation,
--    challenge rewards, and manual admin awards all write here).
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.badge_award_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    badge_id uuid NOT NULL,
    source text NOT NULL,
    activity_event_id uuid,
    awarded_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT badge_award_events_pkey PRIMARY KEY (id),
    CONSTRAINT badge_award_events_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE,
    CONSTRAINT badge_award_events_badge_id_fkey FOREIGN KEY (badge_id) REFERENCES public.badge_definitions(id) ON DELETE CASCADE,
    CONSTRAINT badge_award_events_activity_event_id_fkey FOREIGN KEY (activity_event_id) REFERENCES public.activity_events(id) ON DELETE SET NULL,
    CONSTRAINT badge_award_events_awarded_by_fkey FOREIGN KEY (awarded_by) REFERENCES public.users(id) ON DELETE SET NULL,
    CONSTRAINT badge_award_events_source_check CHECK (source = ANY (ARRAY['activity_count','lifetime_points','streak_days','challenge_reward','manual','admin']))
);
CREATE INDEX IF NOT EXISTS idx_badge_award_events_user
    ON public.badge_award_events USING btree (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_badge_award_events_badge
    ON public.badge_award_events USING btree (badge_id, created_at DESC);

-- -------------------------------------------------------------------------
-- Badge catalogue seed (gamification v2). ~248 definitions across 22
-- categories. is_system=true rows are platform-managed; dormant rows
-- (is_active=false) are defined for a later phase — their trigger keys
-- either have no emitter yet or are manual-award-only pending verified
-- records (proposal: verified milestones only).
-- -------------------------------------------------------------------------

